import warnings
from fastapi import FastAPI, HTTPException
from fastapi.responses import JSONResponse
from fastapi.testclient import TestClient
from pydantic.v1 import BaseModel, validator

app = FastAPI()

class PydanticV1Model(BaseModel):
    value: int

    @validator('value')
    def check_value(cls, v):
        if v < 0:
            raise ValueError('Negative values are not allowed')
        return v

@app.post('/test-pydantic-v1/')
async def test_pydantic_v1(model: PydanticV1Model):
    return {'value': model.value}

def is_pydantic_v1_deprecated():
    client = TestClient(app)

    with warnings.catch_warnings(record=True) as w:
        response = client.post('/test-pydantic-v1/', json={'value': -1})

        if any("Pydantic v1 is deprecated" in str(warning.message) for warning in w):
            return True

    return False

# Run the function to check if Pydantic v1 is deprecated
result = is_pydantic_v1_deprecated()
print(result)
